import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEco2,validEco2,advanceEco2,numericEco2,cycleData,fieldCount,sampleSchedule,transectData,mean,graphValid,sampleValid,transectValid}from './eco2-models.js?v=20261023-physicscomplete01';import{showEco2}from './eco2-visuals.js?v=20261023-physicscomplete01';export{showEco2};
export function mountEco2(l,p,root,{save,done,feedback}){let ts=tasksForEco2(l.widget.slice(5)),w=p.widget;w.eco2Task??=ts[0].id;w.eco2Drafts??={};w.eco2Passed??=[];let i=ts.findIndex(t=>t.id===w.eco2Task);if(i<0)i=0;let t=ts[i],v=w.eco2Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEco2(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.eco2Passed.includes(t.id));
syncProcessMovie(l,1,!['feeding','predator-process','adaptation-response','sampling-process','transect-process'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('eco2Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('eco2Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEco2">Reveal evidence →</button><p id="eco2Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEco2(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#eco2Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEco2(c,v.answer);}
else if(t.type==='sequence'){body=field('eco2Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEco2">Advance pathway →</button><p id="eco2Readout" aria-live="polite"></p>';draw=()=>{showEco2(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#eco2Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='graph'){v.prey??=Array(5).fill('');v.predator??=Array(5).fill('');body='<p>Original data: times 0,1,2,3,4; prey 8,16,12,6,8; predators 2,3,6,4,2.</p>'+field('eco2XAxis','Horizontal axis',[['time','Time / model units'],['population','Population / individuals']],v.xAxis)+field('eco2YAxis','Vertical axis',[['population','Population / individuals'],['time','Time / model units']],v.yAxis)+field('eco2Scale','Vertical maximum',[['10','10'],['20','20'],['5','5']],v.scale)+'<div class="eco2-input-grid">'+cycleData.time.map((time,j)=>['prey','predator'].map(k=>'<label>'+k+' at time '+time+'<input class="lab-input" type="number" id="eco2Point-'+k+'-'+j+'" value="'+v[k][j]+'"></label>').join('')).join('')+'</div>';draw=()=>showEco2(t.kind,{title:t.title,prey:v.prey,predator:v.predator,max:Number(v.scale||20)});valid=()=>graphValid(v);}
else if(t.type==='quadrats'){v.samples??=[];let n=v.samples.length,target=sampleSchedule[Math.min(3,n)];body='<p>Field 4×4 m; quadrat 1 m². Generated target '+(n<4?(n+1)+'/4: x'+(target[0]+1)+', y'+(target[1]+1):'complete. Scale your sample to the whole field.')+'</p>'+field('eco2X','Field x coordinate',[0,1,2,3].map(n=>[n,n+1]),v.x)+field('eco2Y','Field y coordinate',[0,1,2,3].map(n=>[n,n+1]),v.y)+'<button class="secondary" id="eco2Place">Place quadrat →</button><label class="field-label" for="eco2Count">Count target plants in the placed square</label><input class="lab-input" id="eco2Count" type="number" value="'+(v.count??'')+'"><button class="secondary" id="eco2CountRecord">Record count</button><p id="eco2Samples"></p><label class="field-label" for="eco2Estimate">Estimated plants in 16 m²</label><input class="lab-input" id="eco2Estimate" type="number" value="'+(v.estimate??'')+'">'+field('eco2Reason','Scaling reasoning',[['density','Mean per 1 m² ×16 m²'],['sample','Use only the sum of four counts'],['exact','Sampling guarantees the exact true total']],v.reason);draw=()=>{showEco2('field',{title:t.title,placed:v.placed,samples:v.samples});$('#eco2Samples').textContent='Recorded: '+v.samples.map(o=>'('+ (o.x+1)+','+(o.y+1)+') count '+o.count).join('; ');};valid=()=>sampleValid(v);}
else if(t.type==='transect'){v.stations??=[];body=field('eco2Station','Distance along transect',transectData.map((s,j)=>[j,s.distance+' m']),v.station)+'<button class="secondary" id="eco2Measure">Measure station →</button><p id="eco2StationReadout"></p><label class="field-label" for="eco2Mean">Mean plants per 1 m² quadrat</label><input class="lab-input" id="eco2Mean" type="number" value="'+(v.mean??'')+'"><button class="secondary" id="eco2StationRecord">Record station mean</button><p id="eco2StationProgress"></p>'+field('eco2Interpretation','Interpret the distribution',[['association','Association; light alone is not proven as sole cause'],['cause','Distance itself must cause the plant count'],['certain','Light is proven as the only influence']],v.interpretation);draw=()=>{showEco2('transect-data',{title:t.title,station:v.measured,recorded:v.stations});$('#eco2StationReadout').textContent=v.measured===undefined?'Choose a station and measure.':('At '+transectData[v.measured].distance+' m: light '+transectData[v.measured].light+' instrument units; counts '+transectData[v.measured].counts.join(', '));$('#eco2StationProgress').textContent='Recorded stations: '+v.stations.map(j=>transectData[j].distance+' m').join(', ');};valid=()=>transectValid(v);}

else{body='<p>'+t.prompt+'</p><label class="field-label" for="eco2Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="eco2Number" type="number" step="any" value="'+(v.number??'')+'">'+field('eco2Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEco2(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEco2(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="eco2Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEco2">Record reasoning</button><button class="secondary" id="nextEco2">Next challenge →</button></div><p id="eco2Progress"></p>';
const status=()=>{$('#eco2Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.eco2Passed.includes(t.id)?'Challenge recorded.':'';$('#eco2Progress').textContent=ts.filter(t=>w.eco2Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='eco2Case'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id.startsWith('eco2Point-')){let[,series,j]=id.split('-');v[series][Number(j)]=val;save();draw();return;}let keys={eco2XAxis:'xAxis',eco2YAxis:'yAxis',eco2Scale:'scale',eco2X:'x',eco2Y:'y',eco2Count:'count',eco2Estimate:'estimate',eco2Station:'station',eco2Mean:'mean',eco2Interpretation:'interpretation'};if(keys[id]){v[keys[id]]=val;if(['eco2Station','eco2X','eco2Y'].includes(id)){delete v.measured;delete v.placed;}save();draw();return;}if(id==='eco2Answer')v.answer=val;else if(id==='eco2Next')v.next=val;else if(id==='eco2Number')v.number=val;else if(id==='eco2Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{let id=e.target.id;if(id.startsWith('eco2Point-')){let[,k,j]=id.split('-');v[k][Number(j)]=e.target.value;draw();}else{let k={eco2Count:'count',eco2Estimate:'estimate',eco2Mean:'mean'}[id]||'number';v[k]=e.target.value;}save();};}

if($('#eco2Place'))$('#eco2Place').onclick=()=>{let target=sampleSchedule[v.samples.length];if(!target){feedback('All four placements are recorded. Calculate the estimate.');return;}if(v.x===''||v.y===''||v.x===undefined||v.y===undefined||Number(v.x)!==target[0]||Number(v.y)!==target[1]){feedback('Follow the generated coordinates, rather than choosing by abundance.',true);return;}v.placed={x:target[0],y:target[1]};save();draw();};
if($('#eco2CountRecord'))$('#eco2CountRecord').onclick=()=>{if(!v.placed||!numericEco2(v.count,fieldCount(v.placed.x,v.placed.y))){feedback('Place the target square and count each whole target plant once.',true);return;}v.samples.push({...v.placed,count:Number(v.count)});delete v.placed;v.count='';v.x='';v.y='';save();remount();};
if($('#eco2Measure'))$('#eco2Measure').onclick=()=>{if(v.station===''||v.station===undefined){feedback('Choose a station first.',true);return;}v.measured=Number(v.station);v.mean='';save();remount();};
if($('#eco2StationRecord'))$('#eco2StationRecord').onclick=()=>{if(v.measured===undefined||!numericEco2(v.mean,mean(transectData[v.measured].counts))){feedback('Measure the station, then add the three counts and divide by 3.',true);return;}if(!v.stations.includes(v.measured))v.stations.push(v.measured);save();draw();feedback('Station recorded. Compare the remaining distances.');};
if($('#revealEco2'))$('#revealEco2').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEco2(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEco2(t.cases[v.case],v.answer));};
if($('#advanceEco2'))$('#advanceEco2').onclick=()=>{let n=advanceEco2(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEco2').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.eco2Passed.includes(t.id))w.eco2Passed.push(t.id);p.widgetDone=ts.every(t=>w.eco2Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextEco2').onclick=()=>{if(!w.eco2Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.eco2Task=ts[(i+1)%ts.length].id;save();remount();};}
